/// Expected `getVersion()` of the Level 0 ACL and of the base ACL.
/// [Phase 5] The drill deploys the Level 3 ACL (Core, E1, E2) through LIFECYCLE_L0_ACL_ARTIFACT.
const LEVEL0_VERSION: &str = "ACL v0.10.0";
const BASE_VERSION: &str = "ACL v0.7.0";
/// FHE type byte (index 30) of the test handle: 5 (`euint64`), as in the repo's `S3_CT_HANDLE`.
const HANDLE_FHE_TYPE: u8 = 5;
/// ERC-7201 location of `fhevm.storage.ACLRetirement` (ACL.sol `ACL_RETIREMENT_STORAGE_LOCATION`).
const RETIREMENT_LOCATION: B256 =
    b256!("e6ae1005b480da47ced1ed3eb5869a54ca87c5d592369277249f4148c0e86200");
/// Level 0 Core interface id (`retireAccount() ^ isAccountRetired(address)`).
const DAL_CORE_INTERFACE_ID: [u8; 4] = [0x55, 0x6d, 0x20, 0x88];
/// Latency loop sizes.
const N_FWD: usize = 10;
const N_V2_FWD: usize = 5;
const N_REJ: usize = 5;

