// Env (set by run_p12.sh): P12_RUN; P12_DIR, a fresh directory for the ceremony's files; and P1.1's P11_* and
// P0.4's P04_* (signer, ML-DSA-44 ERC-1271 stack, rewrite table).

use kms_worker::core::profile_q::Statement as WorkerStatement;

const P12_OPERATORS: usize = 13;
/// n - t, with n = 13 and t = 4.
const P12_THRESHOLD: usize = 9;
/// Public local test seeds of the operators' keys: keccak256 of this prefix and a name. Test-only.
const P12_OPERATOR_SEED_LABEL: &str = "fhe-authority-lifecycle/P1.2/operator-key/v1/";

fn p12_run() -> String {
    std::env::var("P12_RUN").unwrap_or_else(|_| "r1".to_string())
}

/// One operator's ML-DSA-65 key (dilithium-py).
struct P12Operator {
    seed: B256,
    pk: Vec<u8>,
}

fn p12_operator(signer: &P11Signer, name: &str) -> anyhow::Result<P12Operator> {
    let seed = keccak256(format!("{P12_OPERATOR_SEED_LABEL}{name}"));
    let v = signer.call(seed, &["pubkey", "--scheme", "ML-DSA-65"])?;
    Ok(P12Operator { seed, pk: hex::decode(v["pk"].as_str().ok_or_else(|| anyhow!("pk missing"))?)? })
}

/// Pure ML-DSA-65, empty context, over the statement's bytes; checked by the tool before it returns.
fn p12_sign(signer: &P11Signer, op: &P12Operator, message: &[u8]) -> anyhow::Result<Vec<u8>> {
    let v = signer.call(op.seed, &["sign", "--scheme", "ML-DSA-65", "--msg", &format!("0x{}", hex::encode(message))])?;
    ensure!(v["self_verified"] == true, "operator signature did not self-verify");
    Ok(hex::decode(v["sig"].as_str().ok_or_else(|| anyhow!("sig missing"))?)?)
}

/// The statement's signed bytes, written out here and checked against the worker's own encoding.
fn p12_message(chain_id: u64, acl: Address, variant: &str, b_q: u64, ics: B256) -> anyhow::Result<Vec<u8>> {
    let v: u8 = match variant {
        "no-root-ecdsa" => 1,
        "strict" => 2,
        other => bail!("unknown variant {other}"),
    };
    let mut m = b"ERC-XXXX Profile Q activation statement v1\0".to_vec();
    m.extend_from_slice(&chain_id.to_be_bytes());
    m.extend_from_slice(acl.as_slice());
    m.push(v);
    m.extend_from_slice(&b_q.to_be_bytes());
    m.extend_from_slice(ics.as_slice());
    let worker = WorkerStatement {
        chain_id,
        acl,
        variant: variant.to_string(),
        activation_block: b_q,
        ics_keccak256: ics,
    }
    .message()
    .map_err(|e| anyhow!(e))?;
    ensure!(worker == m, "the worker's statement encoding differs from the harness's");
    Ok(m)
}

fn p12_write_json(path: &Path, v: &serde_json::Value) -> anyhow::Result<()> {
    std::fs::write(path, serde_json::to_vec_pretty(v)?)?;
    Ok(())
}

/// A statement file: the statement's fields and `(operator index, signature)` entries.
#[allow(clippy::too_many_arguments)]
fn p12_statement_file(
    dir: &Path,
    name: &str,
    chain_id: u64,
    acl: Address,
    variant: &str,
    b_q: u64,
    ics: B256,
    sigs: &[(usize, Vec<u8>)],
) -> anyhow::Result<PathBuf> {
    let path = dir.join(format!("statement-{name}.json"));
    let v = serde_json::json!({
        "statement": {
            "chain_id": chain_id,
            "acl": acl.to_string(),
            "variant": variant,
            "activation_block": b_q,
            "ics_keccak256": ics.to_string(),
        },
        "signatures": sigs
            .iter()
            .map(|(i, s)| serde_json::json!({"operator": i, "signature": format!("0x{}", hex::encode(s))}))
            .collect::<Vec<_>>(),
    });
    p12_write_json(&path, &v)?;
    Ok(path)
}

fn p12_q_config(chain_id: u64, operators: &Path, statement: &Path, ics: &Path) -> ProfileQConfig {
    ProfileQConfig {
        enabled: true,
        chain_id,
        operators_file: Some(operators.to_path_buf()),
        statement_file: Some(statement.to_path_buf()),
        ics_file: Some(ics.to_path_buf()),
        threshold: P12_THRESHOLD,
    }
}

/// Profile H `enforce` with E3 (all three schemes, K8 agree mode): the base every Profile Q worker runs on (Q2).
fn p12_profile_h() -> ProfileHConfig {
    let mut p = profile_h_on("enforce", false);
    p.kda_schemes = ["ML-DSA-44", "ML-DSA-65", "ML-DSA-87"].iter().map(|s| s.to_string()).collect();
    p.kda_k8_mode = "agree:rustcrypto,fips204".to_string();
    p
}

/// `key` sends `delegateForUserDecryption(delegate, dapp, exp)` itself (a local key, funded here). Returns the block.
async fn p12_delegate_local(
    env: &Env,
    acl: &AnvilAcl,
    key: &PrivateKeySigner,
    delegate: Address,
    exp: u64,
) -> anyhow::Result<u64> {
    let _: serde_json::Value = acl
        .provider
        .raw_request("anvil_setBalance".into(), (key.address(), U256::from(1_000_000_000_000_000_000u128)))
        .await?;
    let p = ProviderBuilder::new()
        .wallet(EthereumWallet::from(key.clone()))
        .connect_http(env.anvil_url.clone());
    let receipt = ensure_success(
        ACL::new(acl.acl, &p)
            .delegateForUserDecryption(delegate, acl.dapp, exp)
            .send()
            .await?
            .get_receipt()
            .await?,
        "delegateForUserDecryption (local key)",
    )?;
    Ok(receipt.block_number.unwrap_or_default())
}

/// An anvil account delegates (the harness helper), and the block it happened in.
async fn p12_delegate(acl: &AnvilAcl, delegator: Address, delegate: Address, exp: u64) -> anyhow::Result<u64> {
    acl.delegate(delegator, delegate, acl.dapp, exp).await?;
    Ok(acl.provider.get_block_number().await?)
}

/// One logged row, as `p11_log` with the variant and group in the line (`P12-RESULT`).
#[allow(clippy::too_many_arguments)]
fn p12_log(
    group: &str,
    variant: &str,
    label: &str,
    res: &anyhow::Result<RunResult>,
    expect: Outcome,
    code: &str,
    wall_ms: u128,
    mismatches: &mut Vec<String>,
) {
    match res {
        Ok(rr) => {
            let got_code = rr.error_code.clone().unwrap_or_else(|| "-".into());
            info!(
                "P12-RESULT label={label} version={VERSION} group={group} variant={variant} expected={expect:?} \
                observed={:?} kms_mock_hits={} error_counter={} error_code={got_code} expected_code={code} \
                http={} wall_ms={wall_ms}",
                rr.observed,
                rr.kms_hits,
                rr.error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
                rr.http,
            );
            let refused_ok = rr.observed == Outcome::Rejected && rr.kms_hits == 0;
            let forwarded_ok = rr.observed == Outcome::Forwarded && rr.kms_hits >= 2;
            if (expect == Outcome::Rejected && !refused_ok) || (expect == Outcome::Forwarded && !forwarded_ok) {
                mismatches.push(format!("{label}: expected {expect:?}, observed {:?} (kms hits {})", rr.observed, rr.kms_hits));
            } else if expect == Outcome::Rejected && code != "-" && rr.http && got_code != code {
                mismatches.push(format!("{label}: expected error code {code}, observed {got_code}"));
            }
        }
        Err(e) => {
            info!(
                "P12-RESULT label={label} version={VERSION} group={group} variant={variant} expected={expect:?} \
                observed=HarnessError kms_mock_hits=- error_counter=- error_code=- expected_code={code} http=- \
                wall_ms={wall_ms} error=\"{e:#}\""
            );
            mismatches.push(format!("{label}: harness error {e:#}"));
        }
    }
}

