use alloy::sol_types::SolStruct;
use std::collections::HashMap;

alloy::sol! {
    /// TEST-ONLY: the calls the drill sends to the Level 3 registry (ACL v0.10.0: Core, E1, E2).
    #[sol(rpc)]
    interface IPqAcl {
        function designateSuccessor(address successor) external;
        function acceptSuccession(address account) external;
        function confirmSuccessor() external;
        function cancelSuccessorDesignation() external;
        function successorOf(address account) external view returns (address);
        function successorDelayOf(address account) external view returns (uint64);
        function retireAccount() external;
        function retireAccountWithSig(address account, address successor, uint256[] chainIds, bytes signature) external;
        function multicall(bytes[] data) external returns (bytes[] memory results);
        function allow(bytes32 handle, address account) external;
        function allowForDecryption(bytes32[] handlesList) external;
        function delegateForUserDecryption(address delegate, address contractAddress, uint64 expirationDate) external;
        function revokeDelegationForUserDecryption(address delegate, address contractAddress) external;
        function invalidateDecryptionSignaturesBefore(uint256 timestamp) external;
        function isAccountRetired(address account) external view returns (bool);
    }

    /// TEST-ONLY: the Phase 5 B0 wallet (impl/pq-wallet, PQWallet).
    #[sol(rpc)]
    interface IPqWallet {
        function initialize(address pkBlob, bytes32 pkHash) external;
        function execute(address target, bytes data, bytes signature) external returns (bytes memory result);
        function executeDigest(address target, bytes data) external view returns (bytes32);
        function nonce() external view returns (uint256);
        function key() external view returns (address pkBlob, bytes32 pkHash);
    }

    /// The E2 certificate's typed data (ERC-XXXX, C2).
    struct RetireAccount {
        address account;
        address successor;
        uint256[] chainIds;
    }
}

