/// A provider that signs with `key` (our own test key), funded on anvil.
async fn pq_key_provider(env: &Env, acl: &AnvilAcl, key: &PrivateKeySigner) -> anyhow::Result<DynProvider> {
    let _: serde_json::Value = acl
        .provider
        .raw_request("anvil_setBalance".into(), (key.address(), U256::from(10_000_000_000_000_000_000u128)))
        .await?;
    Ok(ProviderBuilder::new()
        .wallet(EthereumWallet::from(key.clone()))
        .connect_http(env.anvil_url.clone())
        .erased())
}

/// One transaction: simulated first (`eth_call`, for the revert data), then sent with a fixed gas limit, so that a
/// refusal is a mined, reverted transaction. Returns (status, gas used, revert data or "-").
async fn pq_tx(p: &DynProvider, from: Address, to: Address, data: Vec<u8>) -> anyhow::Result<(bool, u64, String)> {
    let tx = TransactionRequest::default().with_from(from).with_to(to).with_input(Bytes::from(data));
    let revert = match p.call(tx.clone()).await {
        Ok(_) => "-".to_string(),
        Err(e) => e
            .as_error_resp()
            .and_then(|r| r.as_revert_data())
            .map(|d| d.to_string())
            .unwrap_or_else(|| format!("error:{}", e.to_string().replace(char::is_whitespace, "_"))),
    };
    let receipt = p.send_transaction(tx.with_gas_limit(3_000_000)).await?.get_receipt().await?;
    Ok((receipt.status(), receipt.gas_used, revert))
}

/// One transaction by `key`, logged as a drill row (`PQ-TX`). `expect_mined` is what the design says it does.
#[allow(clippy::too_many_arguments)]
async fn pq_old_tx(
    env: &Env,
    acl: &AnvilAcl,
    label: String,
    path: &str,
    action: &str,
    key: &PrivateKeySigner,
    to: Address,
    data: Vec<u8>,
    expect_mined: bool,
    mismatches: &mut Vec<String>,
) -> anyhow::Result<bool> {
    let p = pq_key_provider(env, acl, key).await?;
    let (status, gas, revert) = pq_tx(&p, key.address(), to, data).await?;
    let word = |b: bool| if b { "mined" } else { "reverted" };
    info!(
        "PQ-TX label={label} version={VERSION} path={path} action={action} sender={} to={to} expected={} \
        observed={} revert={revert} gas_used={gas}",
        key.address(),
        word(expect_mined),
        word(status)
    );
    if status != expect_mined {
        mismatches.push(format!("{label}: expected {}, observed {}", word(expect_mined), word(status)));
    }
    Ok(status)
}

/// A data contract holding `m`'s prepared public key (the verifier's blob), and keccak256 of the 1,312-byte key.
async fn pq_key_blob(acl: &AnvilAcl, m: &P04Mldsa) -> anyhow::Result<(Address, B256)> {
    let (pk, blob) = m.pubkey()?;
    let at = Address::from_slice(&rand_digest().0[..20]);
    let _: serde_json::Value = acl.provider.raw_request("anvil_setCode".into(), (at, Bytes::from(blob))).await?;
    Ok((at, keccak256(&pk)))
}

/// Deploys the B0 wallet: with a key (a deployed wallet), or without one (code that accounts delegate to).
async fn pq_deploy_wallet(
    acl: &AnvilAcl,
    verifier: Address,
    pk_blob: Address,
    pk_hash: B256,
    what: &str,
) -> anyhow::Result<Address> {
    let art = load_artifact(&PathBuf::from(env("PQ_ARTIFACTS")?).join("PQWallet.json"))?;
    let mut code = art.bytecode.to_vec();
    code.extend((verifier, pk_blob, pk_hash).abi_encode_params());
    deploy_code(&acl.provider, acl.owner, code, what).await
}

/// `wallet.execute(target, data)`, authorized by the wallet's ML-DSA-44 key `m`, relayed by an anvil account.
async fn pq_execute(
    acl: &AnvilAcl,
    m: &P04Mldsa,
    wallet: Address,
    target: Address,
    data: Vec<u8>,
    relayer: Address,
    what: &str,
) -> anyhow::Result<TransactionReceipt> {
    let w = IPqWallet::new(wallet, &acl.provider);
    let data = Bytes::from(data);
    let digest = w.executeDigest(target, data.clone()).call().await?;
    let sig = m.sign(digest)?;
    let receipt = w
        .execute(target, data, Bytes::from(sig))
        .from(relayer)
        .gas(4_000_000)
        .send()
        .await?
        .get_receipt()
        .await?;
    info!(
        "PQ-EXECUTE what=\"{what}\" wallet={wallet} target={target} relayer={relayer} digest={digest} status={} \
        gas_used={}",
        receipt.status(),
        receipt.gas_used
    );
    ensure_success(receipt, what)
}

/// A request of the drill: RFC-016 (`run_v2`) or the legacy gateway path (`run_legacy`).
enum PqReq {
    V2(ReqV2),
    Legacy(Req),
}

/// An ERC-1271 request: `account` signs with its ML-DSA-44 key `m` for `owner`'s handle (direct when they are equal,
/// delegated otherwise).
fn pq_erc1271(label: String, keys: &LocalKeys, account: Address, owner: Address, m: &P04Mldsa, http: bool, expect: Outcome) -> PqReq {
    let mut req = ReqV2::new(label, &keys.uk, owner, vec![], http, expect, "-");
    req.path = if owner == account { "v2-direct" } else { "v2-delegated" };
    req.requester = Some(account);
    req.mldsa = Some(m.clone());
    PqReq::V2(req)
}

/// One logged drill request (`PQ-RESULT`); mismatches are collected and the test fails at the end.
#[allow(clippy::too_many_arguments)]
fn pq_log(
    group: &str,
    path: &str,
    action: &str,
    label: &str,
    res: &anyhow::Result<RunResult>,
    expect: Outcome,
    code: &str,
    wall_ms: u128,
    mismatches: &mut Vec<String>,
) {
    match res {
        Ok(rr) => {
            let got_code = rr.error_code.clone().unwrap_or_else(|| "-".into());
            info!(
                "PQ-RESULT label={label} version={VERSION} group={group} path={path} action={action} expected={expect:?} \
                observed={:?} kms_mock_hits={} error_counter={} error_code={got_code} expected_code={code} http={} \
                wall_ms={wall_ms}",
                rr.observed,
                rr.kms_hits,
                rr.error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
                rr.http,
            );
            let refused_ok = rr.observed == Outcome::Rejected && rr.kms_hits == 0;
            let forwarded_ok = rr.observed == Outcome::Forwarded && rr.kms_hits >= 2;
            if (expect == Outcome::Rejected && !refused_ok) || (expect == Outcome::Forwarded && !forwarded_ok) {
                mismatches.push(format!("{label}: expected {expect:?}, observed {:?} (kms hits {})", rr.observed, rr.kms_hits));
            } else if expect == Outcome::Rejected && code != "-" && rr.http && got_code != code {
                mismatches.push(format!("{label}: expected error code {code}, observed {got_code}"));
            }
        }
        Err(e) => {
            info!(
                "PQ-RESULT label={label} version={VERSION} group={group} path={path} action={action} expected={expect:?} \
                observed=HarnessError kms_mock_hits=- error_counter=- error_code=- expected_code={code} http=- \
                wall_ms={wall_ms} error=\"{e:#}\""
            );
            mismatches.push(format!("{label}: harness error {e:#}"));
        }
    }
}

/// The request harnesses of the drill, one per handle, and the database the requests run against.
struct PqRunner<'a> {
    env: &'a Env,
    acl: &'a AnvilAcl,
    db: Pool<Postgres>,
    cfg: RunCfg,
    rhs: HashMap<B256, RequestHarness<'a>>,
    mismatches: Vec<String>,
}

impl<'a> PqRunner<'a> {
    /// One request on `handle`, under the drill's Profile H and the given Profile Q setting.
    #[allow(clippy::too_many_arguments)]
    async fn run(
        &mut self,
        handle: B256,
        q: &ProfileQConfig,
        group: &str,
        path: &str,
        action: &str,
        req: PqReq,
        expect: Outcome,
        code: &str,
    ) -> anyhow::Result<()> {
        if !self.rhs.contains_key(&handle) {
            let rh = RequestHarness::new(self.env, self.acl, AclKind::Level0, handle).await?;
            self.rhs.insert(handle, rh);
        }
        let rh = self.rhs.get_mut(&handle).ok_or_else(|| anyhow!("no harness for {handle}"))?;
        rh.profile_h = pq_profile_h();
        rh.profile_q = q.clone();
        let started = Instant::now();
        let (label, res) = match &req {
            PqReq::V2(r) => (r.label.clone(), rh.run_v2(&self.db, r, &self.cfg).await),
            PqReq::Legacy(r) => (r.label.clone(), rh.run_legacy(&self.db, r, &self.cfg).await),
        };
        pq_log(group, path, action, &label, &res, expect, code, started.elapsed().as_millis(), &mut self.mismatches);
        Ok(())
    }
}

/// One migrating account: its old ECDSA key, the account that decrypts with a post-quantum key afterwards (W, or A
/// itself in place), and its history.
struct PqPath {
    name: &'static str,
    old: PrivateKeySigner,
    holder: Address,
    holder_key: P04Mldsa,
    history: Vec<B256>,
    /// V's handle, for the rows where A is V's delegate.
    hv: B256,
    /// The holder's own KDA (E3), declared through `execute`.
    kda: P11Key,
}

impl PqPath {
    fn in_place(&self) -> bool {
        self.name.starts_with("B3")
    }
    fn successor(&self) -> bool {
        self.name.starts_with("B2")
    }
    /// The owner of the holder's requests on A's history: W for a carry, A otherwise.
    fn history_owner(&self) -> Address {
        if self.successor() { self.old.address() } else { self.holder }
    }
}

/// Phase 5, Part B on main, the Phase 5 worker (Level 3: Profile H with H6, H7, E3, K8, Profile Q; and Q5 at B_Q).
/// One chain, one Level 3 registry (ACL v0.10.0: Core, E1, E2). Each path moves an account A off its ECDSA key; our own
/// test key plays a key someone else also knows:
/// - B1 (carry): A carries its history to wallet W1 and retires in one multicall; W1 reads through ERC-1271 and E3;
/// - B2d, B2c (successor): A designates W, W accepts through `execute`, D passes, A confirms; then A retires itself
///   (B2d), or a relayer submits A's E2 certificate (B2c); W reads A's handles on the delegated path (ERC-1271);
/// - B3a, B3b (in place): A delegates (EIP-7702) to the wallet's code and sets its key; the host chain disabling the
///   key is simulated: EIP-7851 by the proxy's `0xef0101` answer (B3a), EIP-8298 by adopting the wallet's code (B3b).
/// Then: the old key's off-chain requests on every path; the holder's post-quantum requests; Profile Q (B_Q); the old
/// key's transactions after B_Q and what they enable with Profile Q off and on; the post-quantum requests under Q, and
/// with k = 8 and k = 9 of 13 workers enforcing; Q5 at B_Q for adopted code and for a succession; last, the old key
/// retires a B3 account, which ends its wallet's authority too.
#[rstest]
#[timeout(Duration::from_secs(14400))]
#[tokio::test]
async fn pq_drill() -> anyhow::Result<()> {
    let log_guard = init_tracing();
    let env = Env::load()?;
    let run = pq_run();
    let signer = P11Signer::load()?;
    let e4 = P04Mldsa::load()?;
    let a = Accounts::load(&env).await?;
    let keys = LocalKeys::new()?;
    let acl = deploy_acl(&env, AclKind::Level0, a.owner).await?;
    let base_handle = make_handle(env.chain_id);
    setup_grants(&acl, &a, &keys, base_handle).await?;
    let stack = p04_deploy_stack(&acl, &e4).await?;
    let relayer = a.owner;
    // Delegations last a year: the drill moves the chain's clock forward by two successor delays (D = 7 days).
    let exp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() + 365 * 86_400;
    let dapp = acl.dapp;
    let reg = IPqAcl::new(acl.acl, &acl.provider);
    let template = pq_deploy_wallet(&acl, stack.verifier, Address::ZERO, B256::ZERO, "PQWallet code without a key").await?;
    let l = |g: &str, p: &str, s: &str| format!("pq.{run}.{g}.{p}.{s}");

    // ---- The paths: an old ECDSA key each, a holder key each, three handles of history each.
    let names = ["B1", "B2d", "B2c", "B3a", "B3b"];
    let mut paths: Vec<PqPath> = Vec::new();
    for name in names {
        let old = PrivateKeySigner::from_bytes(&rand_digest())?;
        let holder_key = e4.with_label(&format!("{PQ_KEY_LABEL}{name}"));
        let holder = if name.starts_with("B3") {
            old.address()
        } else {
            let (blob, hash) = pq_key_blob(&acl, &holder_key).await?;
            pq_deploy_wallet(&acl, stack.verifier, blob, hash, &format!("PQWallet of {name}")).await?
        };
        let mut history = Vec::new();
        for _ in 0..PQ_HISTORY {
            let h = make_handle(env.chain_id);
            acl.grant(h, old.address()).await?;
            history.push(h);
        }
        // Before the migration: V delegates to A (A as V's delegate), and A delegates to Dk (D for A).
        let hv = make_handle(env.chain_id);
        acl.grant(hv, a.v).await?;
        acl.delegate(a.v, old.address(), dapp, exp).await?;
        p12_delegate_local(&env, &acl, &old, keys.dk.address(), exp).await?;
        let kda = P11Key::new(&signer, "ML-DSA-44", &format!("pq-holder-{name}"))?;
        info!("PQ-PATH name={name} old={} holder={holder} kda={} history={history:?} hv={hv}", old.address(), kda.kda);
        paths.push(PqPath { name, old, holder, holder_key, history, hv, kda });
    }

    // ---- B1: carry and retire in one multicall sent with A's key (the batch the carry tool sends).
    {
        let b = &paths[0];
        let mut calls: Vec<Bytes> = b
            .history
            .iter()
            .map(|h| Bytes::from(IPqAcl::allowCall { handle: *h, account: b.holder }.abi_encode()))
            .collect();
        calls.push(Bytes::from(IPqAcl::retireAccountCall {}.abi_encode()));
        let p = pq_key_provider(&env, &acl, &b.old).await?;
        let r = ensure_success(
            IPqAcl::new(acl.acl, &p).multicall(calls).send().await?.get_receipt().await?,
            "B1 carry-and-retire multicall",
        )?;
        info!("PQ-SETUP path=B1 step=carry-and-retire handles={} gas_used={}", b.history.len(), r.gas_used);
    }

    // ---- B2d, B2c: A designates W; W accepts through `execute`; D passes; A confirms.
    for i in [1usize, 2] {
        let b = &paths[i];
        let p = pq_key_provider(&env, &acl, &b.old).await?;
        let r = ensure_success(
            IPqAcl::new(acl.acl, &p).designateSuccessor(b.holder).send().await?.get_receipt().await?,
            "designateSuccessor",
        )?;
        info!("PQ-SETUP path={} step=designate gas_used={}", b.name, r.gas_used);
        let accept = IPqAcl::acceptSuccessionCall { account: b.old.address() }.abi_encode();
        pq_execute(&acl, &b.holder_key, b.holder, acl.acl, accept, relayer, &format!("{} W accepts", b.name)).await?;
    }
    let delay = reg.successorDelayOf(paths[1].old.address()).call().await?;
    let _: serde_json::Value = acl.provider.raw_request("evm_increaseTime".into(), (delay,)).await?;
    let _: serde_json::Value = acl.provider.raw_request("evm_mine".into(), Vec::<u64>::new()).await?;
    info!("PQ-SETUP step=delay-passed seconds={delay}");
    for i in [1usize, 2] {
        let p = pq_key_provider(&env, &acl, &paths[i].old).await?;
        let r = ensure_success(
            IPqAcl::new(acl.acl, &p).confirmSuccessor().send().await?.get_receipt().await?,
            "confirmSuccessor",
        )?;
        info!("PQ-SETUP path={} step=confirm gas_used={}", paths[i].name, r.gas_used);
    }
    {
        let p = pq_key_provider(&env, &acl, &paths[1].old).await?;
        let r = ensure_success(
            IPqAcl::new(acl.acl, &p).retireAccount().send().await?.get_receipt().await?,
            "B2d retireAccount",
        )?;
        info!("PQ-SETUP path=B2d step=retire gas_used={}", r.gas_used);
    }
    // B2c: A signed its E2 certificate while its key was safe; a relayer submits it (the watchtower's call).
    let domain = Eip712Domain {
        name: Some("DecryptionAuthorityLifecycle".into()),
        version: Some("1".into()),
        chain_id: None,
        verifying_contract: None,
        salt: None,
    };
    ensure!(domain.separator() == PQ_E2_DOMAIN_SEPARATOR, "E2 domain separator differs from the ERC's");
    {
        let b = &paths[2];
        let cert = RetireAccount { account: b.old.address(), successor: b.holder, chainIds: vec![U256::from(env.chain_id)] };
        let digest = cert.eip712_signing_hash(&domain);
        let sig = b.old.sign_hash_sync(&digest)?.as_bytes().to_vec();
        let r = ensure_success(
            reg.retireAccountWithSig(cert.account, cert.successor, cert.chainIds.clone(), Bytes::from(sig))
                .from(relayer)
                .send()
                .await?
                .get_receipt()
                .await?,
            "B2c retireAccountWithSig (relayed)",
        )?;
        info!("PQ-SETUP path=B2c step=certificate-relayed digest={digest} relayer={relayer} gas_used={}", r.gas_used);
    }
    for b in &paths[..3] {
        ensure!(reg.isAccountRetired(b.old.address()).call().await?, "{}: A not retired", b.name);
    }
    for b in &paths[1..3] {
        ensure!(reg.successorOf(b.old.address()).call().await? == b.holder, "{}: W is not A's successor", b.name);
    }

    // ---- B3a, B3b: A delegates (EIP-7702) to the wallet's code and sets its key with a transaction to itself.
    let mut rewrite: Vec<(Address, Address)> = Vec::new();
    for i in [3usize, 4] {
        let b = &paths[i];
        let (blob, hash) = pq_key_blob(&acl, &b.holder_key).await?;
        p04_delegate(&acl, b.old.address(), template).await?;
        let p = pq_key_provider(&env, &acl, &b.old).await?;
        let r = ensure_success(
            IPqWallet::new(b.old.address(), &p).initialize(blob, hash).send().await?.get_receipt().await?,
            "initialize (the account sets its own key)",
        )?;
        info!("PQ-SETUP path={} step=7702-delegate-and-initialize blob={blob} gas_used={}", b.name, r.gas_used);
        if b.name == "B3a" {
            rewrite.push((b.old.address(), template));
        } else {
            // EIP-8298, simulated: A adopts the wallet's regular code; the storage written through the delegation stays.
            let code = acl.provider.get_code_at(template).await?;
            let _: serde_json::Value = acl.provider.raw_request("anvil_setCode".into(), (b.old.address(), code.clone())).await?;
            ensure!(acl.provider.get_code_at(b.old.address()).await? == code, "adopted code not in place");
            let word = acl.provider.get_storage_at(b.old.address(), U256::from_be_bytes(PQ_WALLET_STORAGE.0)).await?;
            ensure!(Address::from_word(B256::from(word)) == blob, "the key slot did not survive the adoption");
            info!(
                "PQ-SETUP path=B3b step=adopt-code code_len={} code_hash={} key_slot={}",
                code.len(),
                keccak256(&code),
                Address::from_word(B256::from(word))
            );
        }
    }
    p04_set_rewrite(&rewrite)?;

    // ---- The holders declare their KDAs (E3) through `execute`.
    for b in &paths {
        let declare = IPqAcl::delegateForUserDecryptionCall { delegate: b.kda.kda, contractAddress: dapp, expirationDate: exp }.abi_encode();
        pq_execute(&acl, &b.holder_key, b.holder, acl.acl, declare, relayer, &format!("{} holder declares its KDA", b.name)).await?;
    }

    let test_instance = TestInstanceBuilder::default()
        .with_tracing(Some(log_guard))
        .with_db(DbInstance::setup_external().await?)
        .build();
    let mut runner = PqRunner {
        env: &env,
        acl: &acl,
        db: test_instance.db().clone(),
        cfg: RunCfg::harness(),
        rhs: HashMap::new(),
        mismatches: Vec::new(),
    };
    let q_off = ProfileQConfig::default();
    info!(
        "PQ-CONFIG version={VERSION} tree=phase5 run={run} max_attempts={} fast_polling_ms={} b_exec={}",
        runner.cfg.max_attempts,
        runner.cfg.fast_polling.as_millis(),
        ProfileHConfig::default().erc1271_execution_budget
    );
    let sig_rej = "user_signature_rejected";

    // ---- Before B_Q: the old key's off-chain requests (R1-R6) and the holder's post-quantum requests (P1-P3).
    for b in &paths {
        let (n, old, h0) = (b.name, &b.old, b.history[0]);
        let refused_code = if b.in_place() { sig_rej } else { "account_retired" };
        let g = "pre";
        runner.run(h0, &q_off, g, n, "R1.permit.v2-direct", PqReq::V2(ReqV2::new(l(g, n, "R1.permit.v2-direct"), old, old.address(), vec![], false, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
        runner.run(h0, &q_off, g, n, "R2.permit.v2-http", PqReq::V2(ReqV2::new(l(g, n, "R2.permit.v2-http"), old, old.address(), vec![], true, Outcome::Rejected, "-")), Outcome::Rejected, refused_code).await?;
        runner.run(h0, &q_off, g, n, "R3.legacy-direct", PqReq::Legacy(Req::direct(l(g, n, "R3.legacy-direct"), old.address(), Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
        runner.run(b.hv, &q_off, g, n, "R4.v2-delegated.a-for-v", PqReq::V2(ReqV2::new(l(g, n, "R4.v2-delegated.a-for-v"), old, a.v, vec![], false, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
        runner.run(b.hv, &q_off, g, n, "R5.legacy-delegated.a-for-v", PqReq::Legacy(Req::delegated(l(g, n, "R5.legacy-delegated.a-for-v"), old.address(), a.v, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
        // R6: D for A through the delegation A made before migrating (D's own key signs). In place, A is not retired:
        // the delegation stands until the holder revokes it.
        let r6 = if b.in_place() { Outcome::Forwarded } else { Outcome::Rejected };
        runner.run(h0, &q_off, g, n, "R6.v2-delegated.d-for-a", PqReq::V2(ReqV2::new(l(g, n, "R6.v2-delegated.d-for-a"), &keys.dk, old.address(), vec![], false, r6, "-")), r6, "-").await?;
        // P1: the holder's post-quantum key reads the whole history (ERC-1271, Profile H's budget).
        for (k, h) in b.history.iter().enumerate() {
            let s = format!("P1.history.h{k}");
            runner.run(*h, &q_off, g, n, &s, pq_erc1271(l(g, n, &s), &keys, b.holder, b.history_owner(), &b.holder_key, false, Outcome::Forwarded), Outcome::Forwarded, "-").await?;
        }
        let s = "P1.history.h0.http";
        runner.run(h0, &q_off, g, n, s, pq_erc1271(l(g, n, s), &keys, b.holder, b.history_owner(), &b.holder_key, true, Outcome::Forwarded), Outcome::Forwarded, "-").await?;
        // P2: E3, the holder's own KDA. For a successor, A's handles are not reachable through it (S9; D98).
        let p2 = if b.successor() { Outcome::Rejected } else { Outcome::Forwarded };
        let s = "P2.e3.kda";
        runner.run(h0, &q_off, g, n, s, PqReq::V2(p11_kda_req(l(g, n, s), &b.kda, P11Sig::Valid, None, b.history_owner(), false, p2)?), p2, "-").await?;
    }
    // P3: a handle granted to A after the migration. A carry does not follow it (the grant to a retired account is
    // inert); a successor reads it; in place, A reads it itself.
    for b in &paths {
        let late = make_handle(env.chain_id);
        acl.grant(late, b.old.address()).await?;
        let expect = if b.name == "B1" { Outcome::Rejected } else { Outcome::Forwarded };
        let s = "P3.late-grant";
        runner.run(late, &q_off, "pre", b.name, s, pq_erc1271(l("pre", b.name, s), &keys, b.holder, b.history_owner(), &b.holder_key, false, expect), expect, "-").await?;
    }

    // ---- Profile Q: 13 operators (ML-DSA-65) sign the no-root-ecdsa statement for B_Q, a few blocks ahead.
    let dir = PathBuf::from(std::env::var("P12_DIR").map_err(|_| anyhow!("missing env var P12_DIR"))?);
    std::fs::create_dir_all(&dir)?;
    let b_q = acl.provider.get_block_number().await? + 5;
    let operators: Vec<P12Operator> =
        (0..P12_OPERATORS).map(|i| p12_operator(&signer, &format!("operator-{i}"))).collect::<anyhow::Result<_>>()?;
    let operators_file = dir.join("operators.json");
    p12_write_json(&operators_file, &serde_json::json!({
        "scheme": "ML-DSA-65",
        "public_keys": operators.iter().map(|o| format!("0x{}", hex::encode(&o.pk))).collect::<Vec<_>>(),
    }))?;
    let ics_file = dir.join("ics.json");
    p12_write_json(&ics_file, &serde_json::json!({
        "ics": "fhe-authority-lifecycle reference deployment, Phase 5 drill (local)",
        "chain_id": env.chain_id, "acl": acl.acl.to_string(),
        "profile_q": {"n": 13, "t": 4, "threshold": P12_THRESHOLD, "operator_scheme": "ML-DSA-65"},
    }))?;
    let ics = keccak256(std::fs::read(&ics_file)?);
    let msg = p12_message(env.chain_id, acl.acl, "no-root-ecdsa", b_q, ics)?;
    let sigs: Vec<(usize, Vec<u8>)> =
        operators.iter().enumerate().map(|(i, o)| Ok((i, p12_sign(&signer, o, &msg)?))).collect::<anyhow::Result<_>>()?;
    let statement = p12_statement_file(&dir, "no-root-ecdsa-13", env.chain_id, acl.acl, "no-root-ecdsa", b_q, ics, &sigs)?;
    let q_on = p12_q_config(env.chain_id, &operators_file, &statement, &ics_file);
    // A6 and A7 (Q5 at B_Q): EOAs before B_Q, each with a handle.
    let a6 = PrivateKeySigner::from_bytes(&rand_digest())?;
    let a7 = PrivateKeySigner::from_bytes(&rand_digest())?;
    let (h6, h7) = (make_handle(env.chain_id), make_handle(env.chain_id));
    acl.grant(h6, a6.address()).await?;
    acl.grant(h7, a7.address()).await?;
    let now = acl.provider.get_block_number().await?;
    ensure!(now < b_q, "the setup passed B_Q");
    let _: serde_json::Value = acl.provider.raw_request("anvil_mine".into(), (U256::from(b_q - now),)).await?;
    ensure!(acl.provider.get_block_number().await? >= b_q, "not at B_Q");
    info!("PQ-BQ b_q={b_q} operators={} threshold={} a6={} a7={}", P12_OPERATORS, P12_THRESHOLD, a6.address(), a7.address());

    // ---- After B_Q: the old key's transactions (T1-T7). Refused after retirement; on this local chain, which does not
    // enforce EIP-7851 or EIP-8298, mined for an account that migrated in place.
    let attacker = PrivateKeySigner::from_bytes(&rand_digest())?;
    let kda_x = P11Key::new(&signer, "ML-DSA-44", "pq-attacker")?;
    for b in &paths {
        let (n, old, h0, h1) = (b.name, &b.old, b.history[0], b.history[1]);
        let mined = b.in_place();
        let mm = &mut runner.mismatches;
        pq_old_tx(&env, &acl, l("tx", n, "T1.allow"), n, "T1.allow", old, acl.acl, IPqAcl::allowCall { handle: h0, account: attacker.address() }.abi_encode(), mined, mm).await?;
        pq_old_tx(&env, &acl, l("tx", n, "T2.allowForDecryption"), n, "T2.allowForDecryption", old, acl.acl, IPqAcl::allowForDecryptionCall { handlesList: vec![h1] }.abi_encode(), mined, mm).await?;
        pq_old_tx(&env, &acl, l("tx", n, "T3.delegate-to-kda"), n, "T3.delegate-to-kda", old, acl.acl, IPqAcl::delegateForUserDecryptionCall { delegate: kda_x.kda, contractAddress: dapp, expirationDate: exp }.abi_encode(), mined, mm).await?;
        pq_old_tx(&env, &acl, l("tx", n, "T4.designateSuccessor"), n, "T4.designateSuccessor", old, acl.acl, IPqAcl::designateSuccessorCall { successor: attacker.address() }.abi_encode(), mined, mm).await?;
        pq_old_tx(&env, &acl, l("tx", n, "T5.confirmSuccessor"), n, "T5.confirmSuccessor", old, acl.acl, IPqAcl::confirmSuccessorCall {}.abi_encode(), false, mm).await?;
        let cert = RetireAccount { account: old.address(), successor: attacker.address(), chainIds: vec![U256::from(env.chain_id)] };
        let sig = old.sign_hash_sync(&cert.eip712_signing_hash(&domain))?.as_bytes().to_vec();
        let data = IPqAcl::retireAccountWithSigCall { account: cert.account, successor: cert.successor, chainIds: cert.chainIds.clone(), signature: Bytes::from(sig) }.abi_encode();
        pq_old_tx(&env, &acl, l("tx", n, "T6.certificate"), n, "T6.certificate", &attacker, acl.acl, data, false, mm).await?;
        // T7 names a time two hours before the wall clock: the permits signed before it stop counting. (0 would mean
        // the block's time, which runs days ahead of the wall clock here after the delays passed.)
        let t7 = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() - 7_200;
        pq_old_tx(&env, &acl, l("tx", n, "T7.invalidateSignaturesBefore"), n, "T7.invalidateSignaturesBefore", old, acl.acl, IPqAcl::invalidateDecryptionSignaturesBeforeCall { timestamp: U256::from(t7) }.abi_encode(), true, mm).await?;
        if !b.in_place() {
            pq_old_tx(&env, &acl, l("tx", n, "T8.retireAccount"), n, "T8.retireAccount", old, acl.acl, IPqAcl::retireAccountCall {}.abi_encode(), false, mm).await?;
        }
    }

    // ---- What those transactions enable, with Profile Q off and on (E1: the attacker's forged grant; E2: the
    // attacker's KDA declared by the old key).
    for (g, q) in [("effect-q-off", &q_off), ("effect-q-on", &q_on)] {
        for b in &paths {
            let (n, h0) = (b.name, b.history[0]);
            let e1 = if b.in_place() && g == "effect-q-off" { Outcome::Forwarded } else { Outcome::Rejected };
            runner.run(h0, q, g, n, "E1.attacker-after-forged-grant", PqReq::V2(ReqV2::new(l(g, n, "E1.attacker-after-forged-grant"), &attacker, attacker.address(), vec![], false, e1, "-")), e1, "-").await?;
            // Under Q, Q5 cuts off a delegation changed after B_Q from an ECDSA-rooted delegator: B3a's code reads as
            // an EIP-7851 indicator; B3b's code was already regular at B_Q, so only the host chain closes that door.
            let e2 = if !b.in_place() { Outcome::Rejected } else if g == "effect-q-off" || n == "B3b" { Outcome::Forwarded } else { Outcome::Rejected };
            runner.run(h0, q, g, n, "E2.attacker-kda", PqReq::V2(p11_kda_req(l(g, n, "E2.attacker-kda"), &kda_x, P11Sig::Valid, None, b.old.address(), false, e2)?), e2, "-").await?;
        }
    }
    // The holder undoes, through `execute`, what the old key did in place: the delegations to D and to the attacker's
    // KDA, and the attacker's designation. Then R6 and E2 are refused.
    for i in [3usize, 4] {
        let b = &paths[i];
        let n = b.name;
        for (what, data) in [
            ("revokes the delegation to D", IPqAcl::revokeDelegationForUserDecryptionCall { delegate: keys.dk.address(), contractAddress: dapp }.abi_encode()),
            ("revokes the attacker's KDA", IPqAcl::revokeDelegationForUserDecryptionCall { delegate: kda_x.kda, contractAddress: dapp }.abi_encode()),
            ("cancels the attacker's designation", IPqAcl::cancelSuccessorDesignationCall {}.abi_encode()),
        ] {
            pq_execute(&acl, &b.holder_key, b.holder, acl.acl, data, relayer, &format!("{n} holder {what}")).await?;
        }
        let h0 = b.history[0];
        runner.run(h0, &q_off, "undone", n, "R6.v2-delegated.d-for-a", PqReq::V2(ReqV2::new(l("undone", n, "R6.v2-delegated.d-for-a"), &keys.dk, b.old.address(), vec![], false, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
        runner.run(h0, &q_off, "undone", n, "E2.attacker-kda", PqReq::V2(p11_kda_req(l("undone", n, "E2.attacker-kda"), &kda_x, P11Sig::Valid, None, b.old.address(), false, Outcome::Rejected)?), Outcome::Rejected, "-").await?;
    }

    // ---- B4: Profile Q after B_Q. ECDSA-rooted requests are refused; the post-quantum requests of every path are
    // served (no-root-ecdsa: regular code through ERC-1271, and E3).
    let g = "q";
    runner.run(base_handle, &q_on, g, "-", "Q.ecdsa-eoa", PqReq::V2(ReqV2::new(l(g, "-", "Q.ecdsa-eoa"), &keys.uk, keys.uk.address(), vec![], false, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
    runner.run(base_handle, &q_on, g, "-", "Q.legacy-direct", PqReq::Legacy(Req::direct(l(g, "-", "Q.legacy-direct"), a.u, Outcome::Rejected, "-")), Outcome::Rejected, "-").await?;
    for b in &paths {
        let (n, h0) = (b.name, b.history[0]);
        runner.run(h0, &q_on, g, n, "Q.P1.history.h0", pq_erc1271(l(g, n, "Q.P1.history.h0"), &keys, b.holder, b.history_owner(), &b.holder_key, false, Outcome::Forwarded), Outcome::Forwarded, "-").await?;
        if !b.successor() {
            runner.run(h0, &q_on, g, n, "Q.P2.e3.kda", PqReq::V2(p11_kda_req(l(g, n, "Q.P2.e3.kda"), &b.kda, P11Sig::Valid, None, b.history_owner(), false, Outcome::Forwarded)?), Outcome::Forwarded, "-").await?;
        }
    }

    // ---- B4, partial adoption: k of 13 workers enforce Profile Q (one database each), k = 8 and 9, on an ECDSA
    // request and on the post-quantum requests of each path. The shares are counted by the analyzer.
    let mut dbs = Vec::with_capacity(P12_OPERATORS);
    for _ in 0..P12_OPERATORS {
        dbs.push(DbInstance::setup_external().await?);
    }
    for k in [8usize, 9] {
        for (i, wdb) in dbs.iter().enumerate() {
            let enforcing = i < k;
            let q = if enforcing { q_on.clone() } else { ProfileQConfig::default() };
            let g = format!("adoption.k{k:02}");
            let mut reqs: Vec<(B256, String, PqReq, Outcome)> = Vec::new();
            let s = format!("ecdsa-eoa.w{i:02}");
            let ecdsa = if enforcing { Outcome::Rejected } else { Outcome::Forwarded };
            reqs.push((base_handle, s.clone(), PqReq::V2(ReqV2::new(l(&g, "-", &s), &keys.uk, keys.uk.address(), vec![], false, ecdsa, "-")), ecdsa));
            for b in &paths {
                let s = format!("{}.P1.w{i:02}", b.name);
                reqs.push((b.history[0], s.clone(), pq_erc1271(l(&g, b.name, &s), &keys, b.holder, b.history_owner(), &b.holder_key, false, Outcome::Forwarded), Outcome::Forwarded));
            }
            for (handle, s, req, expect) in reqs {
                let rh = match runner.rhs.get_mut(&handle) {
                    Some(rh) => rh,
                    None => bail!("no harness for {handle}"),
                };
                rh.profile_h = pq_profile_h();
                rh.profile_q = q.clone();
                let started = Instant::now();
                let (label, res) = match &req {
                    PqReq::V2(r) => (r.label.clone(), rh.run_v2(&wdb.db, r, &runner.cfg).await),
                    PqReq::Legacy(r) => (r.label.clone(), rh.run_legacy(&wdb.db, r, &runner.cfg).await),
                };
                let (observed, hits) = match &res {
                    Ok(rr) => (format!("{:?}", rr.observed), rr.kms_hits.to_string()),
                    Err(_) => ("HarnessError".to_string(), "-".to_string()),
                };
                info!("PQ-ADOPTION k={k} worker={i} enforcing={enforcing} request={s} observed={observed} kms_mock_hits={hits}");
                pq_log(&g, "-", &s, &label, &res, expect, "-", started.elapsed().as_millis(), &mut runner.mismatches);
            }
        }
    }

    // ---- Q5 at B_Q, adopted code (A6): after B_Q the old key declares a KDA, then A delegates to the wallet's code,
    // sets its key and adopts the code. Its code is regular now but was empty at B_Q, so the cutoff applies: the
    // forged KDA is refused; so is a KDA the wallet declares after the adoption (the adoption block is unknown).
    let kda_6x = P11Key::new(&signer, "ML-DSA-44", "pq-a6-forged")?;
    let kda_6y = P11Key::new(&signer, "ML-DSA-44", "pq-a6-wallet")?;
    p12_delegate_local(&env, &acl, &a6, kda_6x.kda, exp).await?;
    let a6_key = e4.with_label(&format!("{PQ_KEY_LABEL}A6"));
    {
        let (blob, hash) = pq_key_blob(&acl, &a6_key).await?;
        p04_delegate(&acl, a6.address(), template).await?;
        let p = pq_key_provider(&env, &acl, &a6).await?;
        ensure_success(IPqWallet::new(a6.address(), &p).initialize(blob, hash).send().await?.get_receipt().await?, "A6 initialize")?;
        let code = acl.provider.get_code_at(template).await?;
        let _: serde_json::Value = acl.provider.raw_request("anvil_setCode".into(), (a6.address(), code)).await?;
        let declare = IPqAcl::delegateForUserDecryptionCall { delegate: kda_6y.kda, contractAddress: dapp, expirationDate: exp }.abi_encode();
        pq_execute(&acl, &a6_key, a6.address(), acl.acl, declare, relayer, "A6 wallet declares a KDA after the adoption").await?;
    }
    runner.run(h6, &q_on, "q5", "A6", "Q5.adopted.forged-kda", PqReq::V2(p11_kda_req(l("q5", "A6", "Q5.adopted.forged-kda"), &kda_6x, P11Sig::Valid, None, a6.address(), false, Outcome::Rejected)?), Outcome::Rejected, "-").await?;
    runner.run(h6, &q_on, "q5", "A6", "Q5.adopted.wallet-kda", PqReq::V2(p11_kda_req(l("q5", "A6", "Q5.adopted.wallet-kda"), &kda_6y, P11Sig::Valid, None, a6.address(), false, Outcome::Rejected)?), Outcome::Rejected, "-").await?;
    runner.run(h6, &q_on, "q5", "A6", "Q5.adopted.wallet-erc1271", pq_erc1271(l("q5", "A6", "Q5.adopted.wallet-erc1271"), &keys, a6.address(), a6.address(), &a6_key, false, Outcome::Forwarded), Outcome::Forwarded, "-").await?;
    runner.run(h6, &q_off, "q5", "A6", "Q5.adopted.forged-kda.q-off", PqReq::V2(p11_kda_req(l("q5", "A6", "Q5.adopted.forged-kda.q-off"), &kda_6x, P11Sig::Valid, None, a6.address(), false, Outcome::Forwarded)?), Outcome::Forwarded, "-").await?;

    // ---- Q5 at B_Q, a succession (A7): after B_Q the old key designates the attacker's wallet X7, X7 accepts, D
    // passes, the old key confirms and retires A7. With Q off X7 reads A7's handle (the asserted residual of E1);
    // under Q it is refused, since X7 was not A7's successor at B_Q. W2, confirmed before B_Q, is served (above).
    let x7_key = e4.with_label(&format!("{PQ_KEY_LABEL}X7-attacker"));
    let (x7_blob, x7_hash) = pq_key_blob(&acl, &x7_key).await?;
    let x7 = pq_deploy_wallet(&acl, stack.verifier, x7_blob, x7_hash, "PQWallet X7 (the attacker's)").await?;
    {
        let p = pq_key_provider(&env, &acl, &a7).await?;
        ensure_success(IPqAcl::new(acl.acl, &p).designateSuccessor(x7).send().await?.get_receipt().await?, "A7 designates X7")?;
        pq_execute(&acl, &x7_key, x7, acl.acl, IPqAcl::acceptSuccessionCall { account: a7.address() }.abi_encode(), relayer, "X7 accepts").await?;
        let delay = reg.successorDelayOf(a7.address()).call().await?;
        let _: serde_json::Value = acl.provider.raw_request("evm_increaseTime".into(), (delay,)).await?;
        let _: serde_json::Value = acl.provider.raw_request("evm_mine".into(), Vec::<u64>::new()).await?;
        ensure_success(IPqAcl::new(acl.acl, &p).confirmSuccessor().send().await?.get_receipt().await?, "A7 confirms X7")?;
        ensure_success(IPqAcl::new(acl.acl, &p).retireAccount().send().await?.get_receipt().await?, "A7 retires")?;
    }
    runner.run(h7, &q_off, "q5", "A7", "Q5.succession.after-bq.q-off", pq_erc1271(l("q5", "A7", "Q5.succession.after-bq.q-off"), &keys, x7, a7.address(), &x7_key, false, Outcome::Forwarded), Outcome::Forwarded, "-").await?;
    runner.run(h7, &q_on, "q5", "A7", "Q5.succession.after-bq", pq_erc1271(l("q5", "A7", "Q5.succession.after-bq"), &keys, x7, a7.address(), &x7_key, false, Outcome::Rejected), Outcome::Rejected, "-").await?;

    // ---- Last: on this local chain the old key can still retire a B3 account, which ends its wallet's authority too
    // (why B3 does not combine with Core retirement).
    for i in [3usize, 4] {
        let b = &paths[i];
        let n = b.name;
        pq_old_tx(&env, &acl, l("tx", n, "T8.retireAccount"), n, "T8.retireAccount", &b.old, acl.acl, IPqAcl::retireAccountCall {}.abi_encode(), true, &mut runner.mismatches).await?;
        let h0 = b.history[0];
        runner.run(h0, &q_off, "after-t8", n, "P4.holder-after-retirement", pq_erc1271(l("after-t8", n, "P4.holder-after-retirement"), &keys, b.holder, b.holder, &b.holder_key, true, Outcome::Rejected), Outcome::Rejected, "account_retired").await?;
    }

    info!("PQ-SUMMARY version={VERSION} tree=phase5 run={run} mismatches={}", runner.mismatches.len());
    ensure!(runner.mismatches.is_empty(), "drill rows differ from the expectation: {:#?}", runner.mismatches);
    Ok(())
}
